import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.DzNHXt93.js";const h=JSON.parse('{"title":"0012 — Artifacts use content-addressed upload","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0012-artifacts-use-content-addressed-upload.md","filePath":"spec/decisions/0012-artifacts-use-content-addressed-upload.md"}'),n={name:"spec/decisions/0012-artifacts-use-content-addressed-upload.md"};function o(d,e,r,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="_0012-—-artifacts-use-content-addressed-upload" tabindex="-1">0012 — Artifacts use content-addressed upload <a class="header-anchor" href="#_0012-—-artifacts-use-content-addressed-upload" aria-label="Permalink to &quot;0012 — Artifacts use content-addressed upload&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-08-06</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Decision <a href="./0002-artifact-urls-are-credential-free-state.html">0002</a> made artifact sources credential-free HTTPS URLs fetched by the host. That keeps secrets out of state, but it forces every deployment to publish a world-readable artifact endpoint, makes the host&#39;s fetch path a hidden availability dependency, leaves media-type and layout validation implicit, and cannot express a multi-module worker bundle (main module, additional modules, WASM, source maps) as one verified unit.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The v1alpha3 lane replaces external artifact URLs with a content-addressed upload API on the host:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST   /artifacts/uploads</span></span>
<span class="line"><span>PUT    /artifacts/uploads/{uploadId}/blobs/{sha256}</span></span>
<span class="line"><span>POST   /artifacts/uploads/{uploadId}/commit</span></span>
<span class="line"><span>GET    /artifacts/{manifestDigest}</span></span>
<span class="line"><span>HEAD   /artifacts/blobs/{sha256}</span></span>
<span class="line"><span>DELETE /artifacts/uploads/{uploadId}</span></span></code></pre></div><p>The client computes blob digests locally, asks the host which blobs are missing, uploads only those, and commits a canonical manifest. The host verifies size, digest, and media type per blob, then returns an immutable manifest digest. Desired state references only that manifest digest; raw code bytes and upload endpoints never enter Terraform state.</p><p>An artifact manifest is a typed, canonical document (for example <code>artifacts.takoform.com/v1alpha1</code> <code>WorkerBundle</code> with <code>mainModule</code> and a <code>modules[]</code> list of name, media type, size, digest). Media types are closed per manifest kind. Archives are transport only; a tar or zip byte stream is never a semantic identity.</p><p>&quot;Closed per manifest kind&quot; is closed <strong>against the runtime</strong>, not against a list this document keeps. A <code>WorkerBundle</code> manifest admits exactly the media types <code>worker.runtime</code> can LOAD, plus the ones a bundle may CARRY and the graph never imports — today source maps alone. A media type in neither is refused, and an auxiliary media type is refused as <code>mainModule</code> while being perfectly admissible in <code>modules</code>. Stating the set anywhere but once, beside the runtime contract that consumes it, is how the manifest and the ABI came to disagree in the first place; the reconciled set and its two classes live in <a href="./0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a> and are enforced in code and conformance under <a href="./0014-published-schemas-are-structural-minima.html">decision 0014</a>, because the published enum states the union and cannot state the split.</p><p>Hosts reject: duplicate module names, absolute paths, <code>..</code>, backslashes, NUL, invalid UTF-8 names, unsupported media types, size or digest mismatches, file count and total-size overruns, a missing main module, a main module the runtime never imports, source maps whose target module is absent, and archive bombs.</p><p>Uploads are resumable: re-asking for missing blobs and re-committing the same manifest is idempotent and converges on the same manifest digest.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>v1alpha3 Form Definitions drop <code>artifactUrl</code>, <code>artifactSha256</code>, <code>artifactMediaType</code>, and artifact-source attributes; revision Forms carry artifact references (<code>bundleRef</code>, module lists) resolved through the upload API.</li><li>The provider computes digests from local files (<code>content_file</code> authoring attributes), performs the upload, and persists only manifest digests.</li><li>Decision 0002 remains the retained rule for the frozen v1alpha1/v1alpha2 lanes; published bytes and their verification are unchanged.</li><li>Conformance gains digest-mismatch, missing-blob, resume, and manifest validation checks.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Keep credential-free URLs alongside uploads.</strong> Rejected because two ingestion paths double the security surface and keep the availability dependency this decision removes.</li><li><strong>Pre-signed host upload URLs outside the API.</strong> Rejected because the contract must stay portable across hosts; pre-signed transport is a host implementation detail behind the same API.</li><li><strong>OCI registry as the required transport.</strong> Rejected because it imports a full registry protocol for what one content-addressed manifest API covers; an OCI adapter can still implement this contract.</li></ul>`,16)])])}const m=a(n,[["render",o]]);export{h as __pageData,m as default};
